<script setup lang="ts">
import {ref,watch} from 'vue';import {api} from './api';
const props=defineProps<{itemId:string}>();const role=ref('reviewer'),days=ref(7),password=ref(''),protectedLink=ref(false),url=ref(''),busy=ref(false),error=ref(''),notice=ref(''),field=ref<HTMLInputElement>();
watch([role,days,password,protectedLink,()=>props.itemId],()=>{url.value='';notice.value='';});
async function create(){busy.value=true;error.value='';notice.value='';try{if(protectedLink.value&&password.value.length<4)throw new Error('请设置至少4位访问密码');const r=await api('/items/'+props.itemId+'/shares','POST',{role:role.value,days:Number(days.value),password:protectedLink.value?password.value:''});url.value=r.url;notice.value=protectedLink.value?'链接已生成，收件人只需输入访问密码，无需账号。':'链接已生成，收件人无需登录即可打开。';}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function copy(){try{await navigator.clipboard.writeText(url.value);notice.value='分享链接已复制';}catch{field.value?.select();notice.value='链接已选中，请复制后发送';}}
async function revoke(){busy.value=true;try{await api('/items/'+props.itemId+'/shares','DELETE',{});url.value='';notice.value='该内容的全部分享链接已撤销';}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><section class="share-settings"><h3>对外分享 · 无需登录</h3><p>生成专用分享链接发送给他人，可选择访问密码。</p><div class="share-settings-fields"><label>访问权限<select v-model="role" :disabled="busy"><option value="viewer">仅可查看</option><option value="reviewer">可查看并评审</option></select></label><label>有效期<select v-model="days" :disabled="busy"><option :value="7">7 天</option><option :value="30">30 天</option><option :value="90">90 天</option></select></label></div><label class="check-label"><input v-model="protectedLink" :disabled="busy" type="checkbox"/>设置访问密码</label><label v-if="protectedLink">访问密码<input v-model="password" :disabled="busy" type="password" autocomplete="new-password" minlength="4" maxlength="64" placeholder="4 至 64 位，单独告知收件人"/></label><div class="inline"><button class="primary" :disabled="busy" @click="create">生成分享链接</button><button class="text-button danger" :disabled="busy" @click="revoke">撤销全部链接</button></div><div v-if="url" class="share-link-row"><input ref="field" :value="url" readonly aria-label="分享链接"/><button class="secondary" @click="copy">复制链接</button><a :href="url" target="_blank" rel="noopener noreferrer">打开</a></div><p v-if="notice" role="status">{{notice}}</p><p v-if="error" class="error-inline" role="alert">{{error}}</p></section></template>
